llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "Omadacycline, a close tetracycline-class analogue, has an absolute oral bioavailability of 34.5% in humans, directly supporting F ≥ 20% for the tetracycline scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Tetracycline itself has an oral bioavailability of 80–90% in humans, indicating that the tetracycline core can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Idarubicin has a median absolute oral bioavailability of 29% in patients, providing additional moderate-F evidence above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Apixaban has an absolute oral bioavailability of about 49–50% in humans, supporting the general feasibility of F ≥ 20% for this query-like molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Loperamide has a very low absolute oral bioavailability of 0.3% in humans, attributed to P-gp efflux and first-pass metabolism; this is contradictory evidence but from a structurally unrelated drug class.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C31"],
      "claim": "Butorphanol has an oral absolute bioavailability of only 5–17% in patients, providing contradictory low-F evidence, though it is not a tetracycline analogue.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a tetracycline-class antibiotic (eravacycline-like). The closest structural analogue, omadacycline, has 34.5% absolute oral bioavailability, and tetracycline itself is 75–90% bioavailable; multiple unrelated drugs with F 27–50% also support F ≥ 20%. Low-F records come from structurally unrelated drugs and are outweighed by the direct tetracycline evidence.",
  "evidence_gaps": [
    "No direct eravacycline oral bioavailability record is present in the evidence set.",
    "One omadacycline record reports an anomalous absolute bioavailability of 0.00663, conflicting with the majority 34.5% value.",
    "The impact of P-gp efflux on eravacycline specifically is not directly measured in the supplied evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

